    "sparql": "SELECT DISTINCT ?zone WHERE { ?zone a brick:HasTimeseries . ?zone brick:hasTimeseries ?timeserie . ?timeserie brick:timeseriesEnergyTotalValue \"2018-04-13\"^^xsd:date ?energy . OPTIONAL { ?timeserie brick:hasTimeseriesEnergyTotalUnit \"kWh\" . } OPTIONAL { ?timeserie brick:hasTimeseriesEnergyTotalValue ?totalenergy . }
